import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.rAhUSuuf.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1771051991000}'),i={name:"guide/getting-started.md"};function l(n,t,s,g,d,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用个人知识库后端系统！本文档将帮助您快速了解和使用本系统。</p><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>个人知识库后端系统是一个基于 <strong>NestJS</strong> 构建的现代化知识库管理系统后端，提供工作空间、文档、块等核心功能的 RESTful API。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li><strong>用户认证</strong> - JWT Token 认证，支持刷新令牌机制</li><li><strong>工作空间管理</strong> - 多工作空间支持，成员权限管理</li><li><strong>文档管理</strong> - 文档树结构，支持父子关系、标签分类</li><li><strong>块级编辑</strong> - 块（Block）作为文档内容的基础单元</li><li><strong>版本控制</strong> - 块版本历史，文档版本管理</li><li><strong>全文搜索</strong> - 基于 PostgreSQL tsvector 的全文搜索</li><li><strong>权限控制</strong> - 细粒度的权限管理（owner、admin、editor、viewer）</li><li><strong>API 文档</strong> - 集成 Swagger/OpenAPI 自动生成 API 文档</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><h3 id="核心框架" tabindex="-1">核心框架 <a class="header-anchor" href="#核心框架" aria-label="Permalink to &quot;核心框架&quot;">​</a></h3><ul><li><strong>NestJS 11.x</strong> - 企业级 Node.js 框架</li><li><strong>TypeScript 5.x</strong> - 类型安全的 JavaScript</li><li><strong>SWC</strong> - 快速编译工具（替代 tsc）</li></ul><h3 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h3><ul><li><strong>PostgreSQL</strong> - 关系型数据库</li><li><strong>TypeORM 0.3.x</strong> - ORM 框架</li></ul><h3 id="认证与安全" tabindex="-1">认证与安全 <a class="header-anchor" href="#认证与安全" aria-label="Permalink to &quot;认证与安全&quot;">​</a></h3><ul><li><strong>Passport.js</strong> - 认证中间件</li><li><strong>JWT</strong> - JSON Web Token 认证</li><li><strong>bcryptjs</strong> - 密码加密</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li>Node.js &gt;= 18.x</li><li>PostgreSQL &gt;= 15</li><li>pnpm &gt;= 8.x（推荐）或 npm/yarn</li></ul>',15)])])}const p=a(i,[["render",l]]);export{u as __pageData,p as default};
